"use client";

import * as React from "react";
import { Table, TableBody } from "@/components/ui/table";
import { cn } from "@/lib/utils";
import { DataTableContext } from "./context";
import { DataTableEmptyState } from "./DataTableEmptyState";
import { DataTableFooter } from "./DataTableFooter";
import { DataTableHeader } from "./DataTableHeader";
import { DataTableLoader } from "./DataTableLoader";
import { DataTableRow } from "./DataTableRow";
import type {
  BaseDataTableProps,
  DataTableColumn,
  RequiredSortProps,
  SortDirection,
  SortProps,
} from "./types";
import {
  computeOrderedColumns,
  computePinOffsets,
  getColumnKey,
  getRecordId,
  useMergedRef,
} from "./utils";

export type {
  DataTableColumn,
  DataTablePaginationProps,
  RowContextMenuItem,
  SortDirection,
  SortStatus,
} from "./types";

const SELECTION_COL_WIDTH = 44;
const EXPAND_COL_WIDTH = 40;
const DEFAULT_PINNED_WIDTH = 150;

export function DataTable<
  T extends Record<string, any>,
  Cols extends readonly DataTableColumn<T>[] = DataTableColumn<T>[],
>(
  props: BaseDataTableProps<T> & {
    columns: Cols;
  } & (Cols[number]["sortable"] extends true
      ? RequiredSortProps<T>
      : SortProps<T>),
) {
  const {
    data,
    fetching = false,
    columns,
    idAccessor,
    selectedRecords,
    onSelectedRecordsChange,
    height,
    noRecordsText = "No records to show",
    highlightOnHover = true,
    onRowClick,
    className,
    variant = "bordered",
    rowClassName,
    rowStyle,
    headerClassName,
    headerStyle,
    renderRowSubContent,
    rowExpandable,
    expandOnRowClick = true,
    singleExpand = false,
    expandedRecordIds,
    onExpandedRecordIdsChange,
    headerRef,
    bodyRef,
    tableRef,
    scrollViewportRef,
    rowRef,
    sortStatus,
    onSortStatusChange,
    children,
  } = props as BaseDataTableProps<T> & SortProps<T>;

  const selectable = !!onSelectedRecordsChange;
  const expandable = !!renderRowSubContent;
  const sticky = !!height;

  /* ------------------------------- Selection ------------------------------ */

  const selectedIds = React.useMemo(
    () =>
      new Set((selectedRecords ?? []).map((r) => getRecordId(r, idAccessor))),
    [selectedRecords, idAccessor],
  );

  const pageSelectedCount = React.useMemo(
    () =>
      data.filter((r) => selectedIds.has(getRecordId(r, idAccessor))).length,
    [data, selectedIds, idAccessor],
  );
  const allChecked = data.length > 0 && pageSelectedCount === data.length;
  const someChecked = pageSelectedCount > 0 && !allChecked;

  // Anchor for shift-click ranges, tracked by id (not index) so it can't
  // point at the wrong row after paging, sorting or refetching.
  const [lastSelectionId, setLastSelectionId] =
    React.useState<React.Key | null>(null);

  // Row handlers read the latest props/state through this ref so their
  // identity never changes. Otherwise every select/expand would hand all
  // memoized rows a new callback and re-render the whole body.
  const latest = React.useRef({
    data,
    idAccessor,
    selectedRecords,
    selectedIds,
    onSelectedRecordsChange,
    lastSelectionId,
    onRowClick,
    rowRef,
  });
  React.useLayoutEffect(() => {
    latest.current = {
      data,
      idAccessor,
      selectedRecords,
      selectedIds,
      onSelectedRecordsChange,
      lastSelectionId,
      onRowClick,
      rowRef,
    };
  });

  const handleToggleSelect = React.useCallback(
    (record: T, rowIndex: number, shiftKey: boolean) => {
      const {
        data,
        idAccessor,
        selectedRecords,
        selectedIds,
        onSelectedRecordsChange,
        lastSelectionId,
      } = latest.current;
      if (!onSelectedRecordsChange) return;
      const id = getRecordId(record, idAccessor);

      const lastSelectionIndex =
        lastSelectionId === null
          ? -1
          : data.findIndex(
              (r) => getRecordId(r, idAccessor) === lastSelectionId,
            );

      if (shiftKey && lastSelectionIndex !== -1) {
        const [start, end] =
          lastSelectionIndex < rowIndex
            ? [lastSelectionIndex, rowIndex]
            : [rowIndex, lastSelectionIndex];
        const rangeRecords = data.slice(start, end + 1);
        const willSelect = !selectedIds.has(id);
        if (willSelect) {
          const merged = [...(selectedRecords ?? [])];
          const existing = new Set(
            merged.map((r) => getRecordId(r, idAccessor)),
          );
          for (const r of rangeRecords) {
            const rid = getRecordId(r, idAccessor);
            if (!existing.has(rid)) {
              merged.push(r);
              existing.add(rid);
            }
          }
          onSelectedRecordsChange(merged);
        } else {
          const rangeIds = new Set(
            rangeRecords.map((r) => getRecordId(r, idAccessor)),
          );
          onSelectedRecordsChange(
            (selectedRecords ?? []).filter(
              (r) => !rangeIds.has(getRecordId(r, idAccessor)),
            ),
          );
        }
      } else if (selectedIds.has(id)) {
        onSelectedRecordsChange(
          (selectedRecords ?? []).filter(
            (r) => getRecordId(r, idAccessor) !== id,
          ),
        );
      } else {
        onSelectedRecordsChange([...(selectedRecords ?? []), record]);
      }
      setLastSelectionId(id);
    },
    [],
  );

  const handleRowClick = React.useCallback((record: T, rowIndex: number) => {
    latest.current.onRowClick?.(record, rowIndex);
  }, []);

  const handleRowRef = React.useCallback(
    (element: HTMLTableRowElement | null, record: T, rowIndex: number) => {
      latest.current.rowRef?.(element, record, rowIndex);
    },
    [],
  );

  const handleToggleAll = React.useCallback(() => {
    if (!onSelectedRecordsChange) return;
    if (allChecked) {
      const idsOnPage = new Set(data.map((r) => getRecordId(r, idAccessor)));
      onSelectedRecordsChange(
        (selectedRecords ?? []).filter(
          (r) => !idsOnPage.has(getRecordId(r, idAccessor)),
        ),
      );
    } else {
      const merged = [...(selectedRecords ?? [])];
      const existing = new Set(merged.map((r) => getRecordId(r, idAccessor)));
      for (const r of data) {
        const id = getRecordId(r, idAccessor);
        if (!existing.has(id)) {
          merged.push(r);
          existing.add(id);
        }
      }
      onSelectedRecordsChange(merged);
    }
  }, [onSelectedRecordsChange, allChecked, data, selectedRecords, idAccessor]);

  /* ------------------------------- Expansion ------------------------------ */

  const [internalExpanded, setInternalExpanded] = React.useState<
    Set<React.Key>
  >(new Set());
  const isExpandControlled = expandedRecordIds !== undefined;
  const expandedSet = React.useMemo(
    () =>
      new Set(
        isExpandControlled ? expandedRecordIds : Array.from(internalExpanded),
      ),
    [isExpandControlled, expandedRecordIds, internalExpanded],
  );

  const expandLatest = React.useRef({
    expandedSet,
    singleExpand,
    isExpandControlled,
    onExpandedRecordIdsChange,
    idAccessor,
  });
  React.useLayoutEffect(() => {
    expandLatest.current = {
      expandedSet,
      singleExpand,
      isExpandControlled,
      onExpandedRecordIdsChange,
      idAccessor,
    };
  });

  const toggleExpand = React.useCallback((record: T) => {
    const {
      expandedSet,
      singleExpand,
      isExpandControlled,
      onExpandedRecordIdsChange,
      idAccessor,
    } = expandLatest.current;
    const id = getRecordId(record, idAccessor);
    let next: Set<React.Key>;
    if (singleExpand) {
      next = expandedSet.has(id) ? new Set() : new Set([id]);
    } else {
      next = new Set(expandedSet);
      if (next.has(id)) next.delete(id);
      else next.add(id);
    }
    if (isExpandControlled) onExpandedRecordIdsChange?.(Array.from(next));
    else setInternalExpanded(next);
  }, []);

  /* --------------------------------- Sort ---------------------------------- */

  const handleSort = React.useCallback(
    (col: DataTableColumn<T>) => {
      if (!col.sortable || !onSortStatusChange) return;
      const isCurrent = sortStatus?.columnAccessor === col.accessor;
      const nextDirection: SortDirection =
        isCurrent && sortStatus?.direction === "asc" ? "desc" : "asc";
      onSortStatusChange({
        columnAccessor: col.accessor,
        direction: nextDirection,
      });
    },
    [onSortStatusChange, sortStatus],
  );

  /* -------------------------------- Pinning -------------------------------- */

  const orderedColumns = React.useMemo(
    () => computeOrderedColumns(columns),
    [columns],
  );
  const leadingGutter =
    (selectable ? SELECTION_COL_WIDTH : 0) +
    (expandable ? EXPAND_COL_WIDTH : 0);

  // Measure the rendered width of every pinned header cell so sticky offsets
  // stay exact for string/omitted widths and for content wider than `width`.
  const headRef = React.useRef<HTMLTableSectionElement>(null);
  const mergedHeadRef = useMergedRef(headRef, headerRef);
  const pinnedKeys = React.useMemo(
    () =>
      orderedColumns
        .filter((c) => c.pinned)
        .map(getColumnKey)
        .join("\u0000"),
    [orderedColumns],
  );
  const [measuredWidths, setMeasuredWidths] = React.useState<
    Record<string, number>
  >({});

  React.useLayoutEffect(() => {
    const thead = headRef.current;
    if (!thead || !pinnedKeys) return;
    const cells = Array.from(
      thead.querySelectorAll<HTMLElement>("th[data-pinned]"),
    );
    const measure = () => {
      const next: Record<string, number> = {};
      for (const cell of cells) {
        const key = cell.dataset.colKey;
        if (key) next[key] = cell.getBoundingClientRect().width;
      }
      setMeasuredWidths((prev) => (sameWidths(prev, next) ? prev : next));
    };
    measure();
    if (typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(measure);
    for (const cell of cells) observer.observe(cell);
    return () => observer.disconnect();
  }, [pinnedKeys]);

  const { leftOffsets, rightOffsets, leftPinnedCols, rightPinnedCols } =
    React.useMemo(
      () =>
        computePinOffsets(
          orderedColumns,
          leadingGutter,
          DEFAULT_PINNED_WIDTH,
          measuredWidths,
        ),
      [orderedColumns, leadingGutter, measuredWidths],
    );

  const pinnedCellStyle = React.useCallback(
    (col: DataTableColumn<T>): React.CSSProperties => {
      const key = getColumnKey(col);
      if (col.pinned === "left")
        return { position: "sticky", left: leftOffsets[key] };
      if (col.pinned === "right")
        return { position: "sticky", right: rightOffsets[key] };
      return {};
    },
    [leftOffsets, rightOffsets],
  );

  const pinnedCellClassName = React.useCallback(
    (
      col: DataTableColumn<T>,
      zIndexClass: string,
      bgClassName: string = "bg-background",
    ) => {
      const isLastLeft =
        leftPinnedCols.length > 0 &&
        leftPinnedCols[leftPinnedCols.length - 1] === col;
      const isFirstRight =
        rightPinnedCols.length > 0 && rightPinnedCols[0] === col;
      return cn(
        col.pinned && "sticky",
        col.pinned && bgClassName,
        col.pinned && zIndexClass,
        col.pinned === "left" &&
          isLastLeft &&
          "shadow-[2px_0_4px_-2px_rgba(0,0,0,0.15)]",
        col.pinned === "right" &&
          isFirstRight &&
          "shadow-[-2px_0_4px_-2px_rgba(0,0,0,0.15)]",
      );
    },
    [leftPinnedCols, rightPinnedCols],
  );

  /* ------------------------------ Scroll shadow ----------------------------- */

  const scrollRef = React.useRef<HTMLDivElement>(null);
  const mergedScrollRef = useMergedRef(scrollRef, scrollViewportRef);
  const [scrollShadow, setScrollShadow] = React.useState({
    left: false,
    right: false,
  });

  const updateScrollShadow = React.useCallback(() => {
    const el = scrollRef.current;
    if (!el) return;
    const left = el.scrollLeft > 1;
    const right = el.scrollLeft + el.clientWidth < el.scrollWidth - 1;
    // Bail out unless an edge actually flipped: scroll fires many times per
    // frame and a fresh object would re-render the whole table each time.
    setScrollShadow((prev) =>
      prev.left === left && prev.right === right ? prev : { left, right },
    );
  }, []);

  const tableElRef = React.useRef<HTMLTableElement>(null);
  const mergedTableRef = useMergedRef(tableElRef, tableRef);

  // Re-check the shadows whenever the viewport or the table itself changes
  // size (sidebar toggles, new data widening a column), not only on window
  // resize.
  React.useEffect(() => {
    updateScrollShadow();
    if (typeof ResizeObserver === "undefined") {
      window.addEventListener("resize", updateScrollShadow);
      return () => window.removeEventListener("resize", updateScrollShadow);
    }
    const observer = new ResizeObserver(updateScrollShadow);
    if (scrollRef.current) observer.observe(scrollRef.current);
    if (tableElRef.current) observer.observe(tableElRef.current);
    return () => observer.disconnect();
  }, [updateScrollShadow]);

  // Content changes don't always resize the table box (e.g. same width,
  // different data), so re-check on those too.
  React.useEffect(updateScrollShadow, [data, orderedColumns]);

  const totalCols =
    orderedColumns.length + (selectable ? 1 : 0) + (expandable ? 1 : 0);

  const contextValue = React.useMemo(
    () => ({ variant, sticky, fetching }),
    [variant, sticky, fetching],
  );

  /* --------------------------------- Render --------------------------------- */

  return (
    <div
      className={cn(
        "rounded-md",
        variant === "bordered" && "border",
        className,
      )}
    >
      <div className="relative">
        <DataTableLoader fetching={fetching} />
        <div
          aria-hidden
          className={cn(
            "pointer-events-none absolute inset-y-0 left-0 z-25 w-6 bg-gradient-to-r from-black/10 to-transparent opacity-0 transition-opacity dark:from-white/10",
            scrollShadow.left && "opacity-100",
          )}
        />
        <div
          aria-hidden
          className={cn(
            "pointer-events-none absolute inset-y-0 right-0 z-25 w-6 bg-gradient-to-l from-black/10 to-transparent opacity-0 transition-opacity dark:from-white/10",
            scrollShadow.right && "opacity-100",
          )}
        />

        <div
          ref={mergedScrollRef}
          onScroll={updateScrollShadow}
          style={height ? { height, overflow: "auto" } : { overflow: "auto" }}
        >
          <Table
            ref={mergedTableRef}
            className="min-w-full"
            style={{
              tableLayout: columns.some((c) => c.width) ? "fixed" : "auto",
            }}
          >
            <DataTableHeader<T>
              ref={mergedHeadRef}
              columns={orderedColumns}
              selectable={selectable}
              expandable={expandable}
              selectionColWidth={SELECTION_COL_WIDTH}
              expandColWidth={EXPAND_COL_WIDTH}
              selectionChecked={allChecked}
              selectionIndeterminate={someChecked}
              onSelectionChange={handleToggleAll}
              sortStatus={sortStatus}
              onSort={handleSort}
              getColumnKey={getColumnKey}
              pinnedCellStyle={pinnedCellStyle}
              pinnedCellClassName={pinnedCellClassName}
              headerClassName={headerClassName}
              headerStyle={headerStyle}
              sticky={sticky}
              variant={variant}
            />

            <TableBody ref={bodyRef}>
              {data.length === 0 ? (
                <DataTableEmptyState
                  text={fetching ? "" : noRecordsText}
                  colSpan={totalCols}
                />
              ) : (
                data.map((record, rowIndex) => {
                  const rowId = getRecordId(record, idAccessor);
                  const isSelected = selectedIds.has(rowId);
                  const isExpanded = expandedSet.has(rowId);
                  const canExpand =
                    expandable &&
                    (rowExpandable ? rowExpandable(record, rowIndex) : true);
                  const resolvedRowClassName =
                    typeof rowClassName === "function"
                      ? rowClassName(record, rowIndex)
                      : rowClassName;
                  const resolvedRowStyle =
                    typeof rowStyle === "function"
                      ? rowStyle(record, rowIndex)
                      : rowStyle;

                  return (
                    <DataTableRow<T>
                      key={rowId}
                      record={record}
                      rowIndex={rowIndex}
                      columns={orderedColumns}
                      selectable={selectable}
                      expandable={expandable}
                      selectionColWidth={SELECTION_COL_WIDTH}
                      expandColWidth={EXPAND_COL_WIDTH}
                      isSelected={isSelected}
                      isExpanded={isExpanded}
                      canExpand={canExpand}
                      renderSubContent={renderRowSubContent}
                      onToggleSelect={handleToggleSelect}
                      onToggleExpand={toggleExpand}
                      onRowClick={onRowClick ? handleRowClick : undefined}
                      expandOnRowClick={expandOnRowClick}
                      highlightOnHover={highlightOnHover}
                      rowClassName={resolvedRowClassName}
                      rowStyle={resolvedRowStyle}
                      getColumnKey={getColumnKey}
                      pinnedCellStyle={pinnedCellStyle}
                      pinnedCellClassName={pinnedCellClassName}
                      leadingGutter={leadingGutter}
                      totalCols={totalCols}
                      variant={variant}
                      rowRef={rowRef ? handleRowRef : undefined}
                    />
                  );
                })
              )}
            </TableBody>

            <DataTableFooter
              columns={orderedColumns}
              data={data}
              selectable={selectable}
              expandable={expandable}
              selectionColWidth={SELECTION_COL_WIDTH}
              expandColWidth={EXPAND_COL_WIDTH}
              getColumnKey={getColumnKey}
              pinnedCellStyle={pinnedCellStyle}
              pinnedCellClassName={pinnedCellClassName}
              sticky={sticky}
              variant={variant}
            />
          </Table>
        </div>
      </div>

      {children != null && (
        <DataTableContext.Provider value={contextValue}>
          {children}
        </DataTableContext.Provider>
      )}
    </div>
  );
}

export default DataTable;

function sameWidths(a: Record<string, number>, b: Record<string, number>) {
  const aKeys = Object.keys(a);
  if (aKeys.length !== Object.keys(b).length) return false;
  // Sub-pixel jitter isn't worth a re-render.
  return aKeys.every((k) => Math.abs(a[k] - (b[k] ?? Number.NaN)) < 0.5);
}

"use client";

import { MoreVertical } from "lucide-react";
import type * as React from "react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import type { RowContextMenuItem } from "./types";

export interface DataTableActionProps {
  /** Menu items — same shape as `DataTableContextMenu`'s per-row `items`, so
   * you can reuse the exact same list for both the right-click context menu
   * and this button. */
  items: RowContextMenuItem[];
  /** Accessible label for the trigger button. */
  label?: string;
  /** Icon shown on the trigger button. Defaults to a vertical 3-dot icon. */
  icon?: React.ReactNode;
  className?: string;
  align?: "start" | "center" | "end";
  side?: "top" | "bottom" | "left" | "right";
}

/**
 * A "kebab" (3-dot) button that opens a menu — meant for a table's actions
 * column. Typically used together with (or instead of) `DataTableContextMenu`:
 *
 *   {
 *     accessor: "actions",
 *     title: "",
 *     width: 60,
 *     render: (record) => (
 *       <DataTableAction
 *         items={[
 *           { key: "edit", label: "Edit", onClick: () => editUser(record) },
 *           { key: "delete", label: "Delete", danger: true, onClick: () => deleteUser(record) },
 *         ]}
 *       />
 *     ),
 *   }
 *
 * Stops click propagation so it's safe to use inside a row that also has
 * `onRowClick` / expandable rows without accidentally triggering those.
 */
export function DataTableAction({
  items,
  label = "Open menu",
  icon,
  className,
  align = "end",
  side = "bottom",
}: DataTableActionProps) {
  if (!items.length) return null;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        className={cn(
          "flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground",
          className,
        )}
        aria-label={label}
        onClick={(e: React.MouseEvent) => e.stopPropagation()}
      >
        {icon ?? <MoreVertical className="h-4 w-4" />}
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align={align}
        side={side}
        onClick={(e: React.MouseEvent) => e.stopPropagation()}
      >
        {items.map((item) => (
          <DropdownMenuItem
            key={item.key}
            disabled={item.disabled}
            onClick={item.onClick}
            className={cn(
              item.danger && "text-destructive focus:text-destructive",
            )}
          >
            {item.icon && (
              <span className="mr-2 flex items-center">{item.icon}</span>
            )}
            {item.label}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import * as React from "react";
import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuTrigger,
} from "@/components/ui/context-menu";
import { cn } from "@/lib/utils";
import {
  type DataTableRowMenuBridge,
  DataTableRowMenuContext,
} from "./context";
import type { RowContextMenuItem } from "./types";

const LONG_PRESS_DELAY = 500;
const LONG_PRESS_MOVE_TOLERANCE = 10;

export interface DataTableContextMenuProps<T> {
  /**
   * Items for the row that was right-clicked (or long-pressed). Called only
   * at that moment, with that row's record, so per-row conditions always see
   * the latest data. Return `undefined` or `[]` to keep the browser's native
   * menu on that row.
   */
  items: (record: T, rowIndex: number) => RowContextMenuItem[] | undefined;
  /** Usually a single `<DataTable />`. */
  children: React.ReactNode;
}

/**
 * Opt-in right-click menu for `DataTable` rows. Wrap the table with it:
 *
 *   <DataTableContextMenu items={getRowActions}>
 *     <DataTable data={rows} columns={columns} />
 *   </DataTableContextMenu>
 *
 * A single menu is shared by every row: rows only forward their right-click,
 * and `items` runs for the clicked row when the menu opens, not on render.
 * Kept out of the core table so tables without a menu never ship it.
 */
export function DataTableContextMenu<T>({
  items,
  children,
}: DataTableContextMenuProps<T>) {
  const [activeItems, setActiveItems] = React.useState<RowContextMenuItem[]>(
    [],
  );
  // Base UI renders the trigger as a <div>, Radix as a <span>.
  const triggerRef = React.useRef<HTMLElement | null>(null);
  const itemsRef = React.useRef(items);
  React.useLayoutEffect(() => {
    itemsRef.current = items;
  });

  const bridge = React.useMemo<DataTableRowMenuBridge>(() => {
    let longPress: {
      timer: ReturnType<typeof setTimeout>;
      x: number;
      y: number;
    } | null = null;

    const cancelLongPress = () => {
      if (longPress) clearTimeout(longPress.timer);
      longPress = null;
    };

    // Opens the shared menu at (x, y) for this record. Returns false when the
    // row has no items, so the caller leaves the native menu alone.
    const openAt = (
      x: number,
      y: number,
      record: unknown,
      rowIndex: number,
    ) => {
      const next = itemsRef.current(record as T, rowIndex);
      const trigger = triggerRef.current;
      if (!next || next.length === 0 || !trigger) return false;
      setActiveItems(next);
      // Re-dispatch on the hidden trigger: both Base UI and Radix anchor the
      // menu at the event's coordinates, so it opens under the cursor.
      trigger.dispatchEvent(
        new MouseEvent("contextmenu", {
          bubbles: true,
          cancelable: true,
          clientX: x,
          clientY: y,
          button: 2,
        }),
      );
      return true;
    };

    return {
      onContextMenu: (event, record, rowIndex) => {
        cancelLongPress();
        if (openAt(event.clientX, event.clientY, record, rowIndex)) {
          event.preventDefault();
        }
      },
      // iOS Safari never fires `contextmenu` on long-press, so emulate it.
      onTouchStart: (event, record, rowIndex) => {
        cancelLongPress();
        if (event.touches.length !== 1) return;
        const { clientX: x, clientY: y } = event.touches[0];
        longPress = {
          x,
          y,
          timer: setTimeout(() => {
            longPress = null;
            openAt(x, y, record, rowIndex);
          }, LONG_PRESS_DELAY),
        };
      },
      onTouchMove: (event) => {
        if (!longPress) return;
        const touch = event.touches[0];
        if (
          !touch ||
          Math.abs(touch.clientX - longPress.x) > LONG_PRESS_MOVE_TOLERANCE ||
          Math.abs(touch.clientY - longPress.y) > LONG_PRESS_MOVE_TOLERANCE
        ) {
          cancelLongPress();
        }
      },
      onTouchEnd: cancelLongPress,
    };
  }, []);

  return (
    <DataTableRowMenuContext.Provider value={bridge}>
      {children}
      <ContextMenu>
        <ContextMenuTrigger
          ref={(el: HTMLElement | null) => {
            triggerRef.current = el;
          }}
          aria-hidden
          tabIndex={-1}
          className="hidden"
        />
        <ContextMenuContent>
          {activeItems.map((item) => (
